// Generated by scripts.prepare_review_assets from the review template.

const data=JSON.parse(document.getElementById('review-data').textContent);
const el=id=>document.getElementById(id), key='tracex.blind-review.'+data.sample_hash;
let state={index:0,reviewer:'',reviews:{}};
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved)state=saved;}catch{el('notice').textContent='Browser storage is unavailable. Export your review before closing.';}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{el('notice').textContent='Could not save locally. Export your current labels.';}}
data.rows.forEach((row,i)=>{const option=document.createElement('option');option.value=i;option.textContent=row.sample_id;el('jump').append(option);});
el('reviewer').value=state.reviewer;
function draw(){
 const row=data.rows[state.index], review=state.reviews[row.sample_id]||{};
 el('title').textContent=row.sample_id+' · '+row.component;
 el('vehicle').textContent=row.year+' '+row.make+' '+row.model+' · Received '+row.datea;
 el('narrative').textContent=row.narrative;el('notes').value=review.notes||'';el('jump').value=state.index;
 const field=el('choices');field.querySelectorAll('label').forEach(x=>x.remove());
 const names=Object.fromEntries(row.allowed_label_text.split(';').filter(x=>x.includes('=')).map(x=>{const at=x.indexOf('=');return [x.slice(0,at).trim(),x.slice(at+1).trim()];}));
 row.allowed_label_ids.split(';').forEach(id=>{const label=document.createElement('label'),input=document.createElement('input');input.type='radio';input.name='defect';input.value=id;input.checked=review.label===id;input.onchange=()=>{state.reviews[row.sample_id]={label:id,notes:el('notes').value};save();draw();};label.append(input,document.createTextNode(names[id]||id));field.append(label);});
 const count=Object.keys(state.reviews).length;el('progressText').textContent=count+' / '+data.rows.length+' reviewed';el('progress').max=data.rows.length;el('progress').value=count;
 el('prev').disabled=state.index===0;el('next').disabled=state.index===data.rows.length-1;
}
function move(i){state.index=i;save();draw();}
el('prev').onclick=()=>move(Math.max(0,state.index-1));el('next').onclick=()=>move(Math.min(data.rows.length-1,state.index+1));el('jump').onchange=e=>move(Number(e.target.value));
el('unreviewed').onclick=()=>{for(let n=1;n<=data.rows.length;n++){const i=(state.index+n)%data.rows.length;if(!state.reviews[data.rows[i].sample_id])return move(i);}};
el('reviewer').oninput=e=>{state.reviewer=e.target.value;save();};
el('notes').oninput=e=>{const row=data.rows[state.index];if(state.reviews[row.sample_id]){state.reviews[row.sample_id].notes=e.target.value;save();}};
el('clear').onclick=()=>{delete state.reviews[data.rows[state.index].sample_id];save();draw();};
el('export').onclick=()=>{
 if(!state.reviewer.trim()||!el('attest').checked||!Object.keys(state.reviews).length){el('notice').textContent='Enter your name, review at least one complaint, and confirm the human-review statement.';return;}
 const result={sample_hash:data.sample_hash,annotation_source:'human',attestation:true,reviewer:state.reviewer.trim(),exported_at:new Date().toISOString(),reviews:Object.entries(state.reviews).map(([sample_id,r])=>({sample_id,...r}))};
 const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='defect-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);el('notice').textContent='Exported '+result.reviews.length+' reviewed labels.';
};draw();

